# III Calculation of the Paycheck: compensation and fringe benefits (24)
CAT = "fpcGross"; SEG = "GRS"
N = {"num": True}
def C(v): return {"num": True, "chk": v}
Q = [
("A nonexempt employee paid $18 an hour works 46 hours in a workweek. Gross pay is:",
 "$882.00", ["$828.00", "$936.00", "$963.00"],
 "40 x $18 = $720 plus 6 x $27 = $162, for $882.00. $828 pays all 46 hours at straight time with no premium.", C(40 * 18 + 6 * 27)),
("A piece-rate worker earns $450 for 500 pieces in a 45-hour workweek. Gross pay with overtime is:",
 "$475.00", ["$450.00", "$500.00", "$525.00"],
 "The regular rate is $450 / 45 = $10.00. Piece pay already covers straight time, so each of the 5 overtime hours adds half the rate: 5 x $5.00 = $25.", C(450 + 5 * 0.5 * (450 / 45))),
("An hourly worker earns $15 an hour for 44 hours plus a $132 commission for the week. Gross pay is:",
 "$828.00", ["$792.00", "$822.00", "$864.00"],
 "Straight pay is $660 + $132 = $792, so the regular rate is $792 / 44 = $18.00 and the premium is 4 x $9.00 = $36. Basing the premium on $15 alone gives $822.", C(44 * 15 + 132 + 4 * 0.5 * ((44 * 15 + 132) / 44))),
("An employee paid $12 an hour works 45 hours and earns a promised $40 attendance bonus. Gross pay is:",
 "$612.22", ["$580.00", "$610.00", "$644.44"],
 "Straight pay is $540 + $40 = $580; the regular rate is $580 / 45 = $12.889, so the premium is 5 x $6.444 = $32.22. A promised bonus is nondiscretionary and must be in the rate.", C(45 * 12 + 40 + 5 * 0.5 * ((45 * 12 + 40) / 45))),
("A nonexempt employee is paid $800 a week for a 40-hour schedule and works 45 hours. Gross pay is:",
 "$950.00", ["$875.00", "$900.00", "$1,000.00"],
 "The salary covers 40 hours, so the regular rate is $20. The 5 extra hours are paid at $30: $800 + $150 = $950. $900 pays the extra hours at straight time.", C(800 + 5 * 1.5 * (800 / 40))),
("Under the fluctuating workweek method, a $900 weekly salary covers all hours and the employee works 50. Gross pay is:",
 "$990.00", ["$900.00", "$1,012.50", "$1,170.00"],
 "29 CFR 778.114: the regular rate is $900 / 50 = $18, and overtime hours get only half that rate: 10 x $9 = $90. $1,012.50 wrongly divides the salary by 40.", C(900 + 10 * 0.5 * (900 / 50))),
("An employee aged 47 has $150,000 of employer-paid group-term life. Using a Table 2-2 cost of $0.15 per $1,000 a month, monthly imputed income is:",
 "$15.00", ["$7.50", "$22.50", "$180.00"],
 "Only coverage over $50,000 counts: 100 x $0.15 = $15.00 a month. $22.50 prices all $150,000, and $180 is the annual figure.", C((150000 - 50000) / 1000 * 0.15)),
("An employee has $200,000 of group-term life at a Table 2-2 cost of $0.10 per $1,000 a month and pays $5.00 a month after tax toward it. Monthly imputed income is:",
 "$10.00", ["$5.00", "$15.00", "$20.00"],
 "Excess coverage is 150 x $0.10 = $15.00, reduced by the $5.00 the employee pays after tax, leaving $10.00. $20 prices the full $200,000.", C((200000 - 50000) / 1000 * 0.10 - 5)),
("A company car has an Annual Lease Value of $6,850 and 30% of its miles are personal. The employee's imputed income is:",
 "$2,055.00", ["$1,027.50", "$4,795.00", "$6,850.00"],
 "Under the lease value rule only the personal share is income: $6,850 x 30% = $2,055. $4,795 is the business share.", C(6850 * 0.30)),
("An employer provides fuel for 4,000 personal miles in a car valued under the lease value rule and uses the per-mile fuel value. Fuel income is:",
 "$220.00", ["$22.00", "$290.00", "$2,200.00"],
 "Pub. 15-B lets fuel be valued at 5.5 cents a mile: 4,000 x $0.055 = $220. The Annual Lease Value never includes fuel.", C(4000 * 0.055)),
("Sick pay from a third-party insurer stops being subject to social security and Medicare once it is paid more than:",
 "6 calendar months after last work", ["3 calendar months after last work", "12 calendar months after last work", "26 weeks after the claim is filed"],
 "Pub. 15-A: FICA and FUTA do not apply to sick pay paid more than 6 calendar months after the last month the employee worked."),
("An employer wants a $1,000 net bonus. With 22% federal, 6.2% social security and 1.45% Medicare and no state tax, the grossed-up bonus is:",
 "$1,421.46", ["$1,082.84", "$1,282.05", "$1,296.50"],
 "Gross-up divides the net by 1 minus the total rate: $1,000 / (1 - 0.2965) = $1,421.46. Multiplying $1,000 by 1.2965 falls short.", C(1000 / (1 - 0.22 - 0.062 - 0.0145))),
("An employee already past the social security wage base gets a $2,000 net bonus. Using 22% federal and 1.45% Medicare only, the grossed-up amount is:",
 "$2,612.67", ["$2,469.00", "$2,564.10", "$2,842.93"],
 "Past the wage base only Medicare applies: $2,000 / (1 - 0.2345) = $2,612.67. $2,842.93 still includes 6.2% social security.", C(2000 / (1 - 0.22 - 0.0145))),
("Under federal law, a terminated employee's final paycheck must be paid:",
 "No federal deadline; states set it", ["By the next regular business day", "Within 72 hours of termination", "By the end of the month"],
 "The DOL says federal law does not require an immediate final paycheck. Many states do set deadlines, so state law governs."),
("A back pay award for a wage claim from two years ago is paid this year. It is taxed as:",
 "Wages in the year paid", ["Wages of the original years", "Nontaxable damages", "Nonemployee compensation"],
 "Pub. 15: back pay, including retroactive raises but not liquidated damages, is taxed as ordinary wages in the year paid. Pub. 957 covers reporting it to SSA."),
("An employee repays wages overpaid in a prior year. On Form 941-X the employer may recover:",
 "Employee FICA, not income tax", ["Income tax, not employee FICA", "Both income tax and FICA", "Neither, once the year closes"],
 "Pub. 15: prior-year repayments let the employer recover social security and Medicare on Form 941-X and correct W-2c boxes 3 and 5, but not income tax withheld."),
("A nonexempt inside salesperson paid only commission earns $250 for a 40-hour week. Federal law requires the employer to add:",
 "$40.00", ["$0.00", "$50.00", "$290.00"],
 "Pay must reach the $7.25 minimum for every hour: 40 x $7.25 = $290, less $250 earned, is $40.", C(40 * 7.25 - 250)),
("A per-hour night shift differential is, for FLSA overtime:",
 "Included in the regular rate", ["Excluded as a premium", "Excluded as a gift", "Excluded if paid weekly"],
 "Fact Sheet #23 excludes only listed payments, such as true overtime premiums and discretionary bonuses. A shift differential is pay for work and goes in the regular rate."),
("A nonexempt employee is paid 8 hours of holiday pay and works 36 hours that week. Overtime hours owed under the FLSA:",
 "0", ["2", "4", "8"],
 "Pay for time not worked, such as holidays, is not hours worked, so 36 hours worked earns no FLSA overtime. A company policy may still pay more.", N),
("Under a qualified educational assistance program, an employer pays $7,000 of an employee's tuition this year. The taxable amount is:",
 "$1,750.00", ["$0.00", "$5,250.00", "$7,000.00"],
 "Up to $5,250 a year is excluded, so $7,000 - $5,250 = $1,750 is wages unless it qualifies as a working condition fringe.", {"num": True, "chk": 7000 - 5250}),
("Wages an employee earned before dying are paid to the estate in the same year. The employer withholds:",
 "Social security and Medicare only", ["Federal income tax only", "All federal taxes, as usual wages", "No federal taxes"],
 "Pub. 15 and the W-2 instructions: same-year wages to the estate are FICA wages in boxes 3 and 5 but not income tax wages in box 1."),
("Final wages are paid to an estate in the calendar year after the employee's death. They are reported on Form:",
 "1099-MISC", ["W-2", "1099-NEC", "1041"],
 "After the year of death the wages are exempt from FICA and withholding and are reported on Form 1099-MISC, not Form W-2."),
("An employee earns $58,500 a year and is paid biweekly. Gross pay each period is:",
 "$2,250.00", ["$1,125.00", "$2,437.50", "$4,875.00"],
 "Biweekly means 26 pay periods: $58,500 / 26 = $2,250. Dividing by 24, the semimonthly count, gives $2,437.50.", C(58500 / 26)),
("A new hire on $62,400 a year starts mid period and works 48 of the 80 hours in the first biweekly period. Prorated gross pay is:",
 "$1,440.00", ["$1,200.00", "$1,560.00", "$2,400.00"],
 "The hourly equivalent is $62,400 / 2,080 = $30, and 48 x $30 = $1,440. $2,400 is a full biweekly period.", C(48 * 62400 / 2080)),
]
